const payload = $json.body || $json;
const action = String(payload.action || '');
const issue = payload.issue || {};
const repo = String(payload.repository?.full_name || '');
const process = ['opened','reopened'].includes(action) && /^[-A-Za-z0-9_.]+\/[-A-Za-z0-9_.]+$/.test(repo) && Number.isInteger(issue.number);
const text = `${issue.title || ''}\n${issue.body || ''}`.toLowerCase();
const rules = [
  { label: 'bug', words: ['bug','error','crash','broken','exception','regression','fails'] },
  { label: 'documentation', words: ['docs','documentation','readme','typo','example'] },
  { label: 'question', words: ['question','how do i','how to','help','?'] },
  { label: 'enhancement', words: ['feature','enhancement','request','proposal','support for'] },
];
const match = rules.find(r => r.words.some(word => text.includes(word)));
return [{ json: { process, repo, issue_number: issue.number, label: match?.label || 'needs-triage', title: issue.title || '', sender: payload.sender?.login || 'unknown' } }];
